<?php
require __DIR__.'/../../config/database.php'; require __DIR__.'/../../config/helpers.php';
if(!isset($_SESSION['ID_USER'])){header('Location: /index.php');exit;} requireRole(0);
$labAtual=max(1,min(4,(int)($_GET['lab']??$_POST['id_lab']??1))); $maquinas=listarMaquinasDoLab($con,$labAtual); $erro=null;
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['sub'])){$idLab=max(1,min(4,(int)($_POST['id_lab']??1)));$idMaq=($_POST['id_maq']??'')===''?0:(int)$_POST['id_maq'];if($idMaq<=0){$erro='Selecione uma máquina para registrar o relatório.';}else{$titulo=trim($_POST['titulo']??'');$descricao=trim($_POST['descricao']??'');$tipo=in_array($_POST['tipo_problema']??'',tiposProblema(),true)?$_POST['tipo_problema']:'Outro';$status=max(1,min(2,(int)($_POST['status']??1)));$data=$_POST['data']??date('Y-m-d');$s=$con->prepare('INSERT INTO Ocorrencias (titulo,descricao,data_ocorr,ID_USER,ID_LAB,ID_MAQ,tipo_problema,status_ocorrencia) VALUES (?,?,?,?,?,?,?,?)');$s->bind_param('sssiiisi',$titulo,$descricao,$data,$_SESSION['ID_USER'],$idLab,$idMaq,$tipo,$status);if($s->execute()){registrarHistorico($con,(int)$s->insert_id,$idLab,$idMaq,$titulo,$tipo,$status,'criada',(int)$_SESSION['ID_USER']);header('Location: /suporte/laboratorio.php?lab='.$idLab);exit;}$erro='Não foi possível registrar a ocorrência.';$s->close();}}
?><!doctype html><html lang="pt-br"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Novo relatório</title><link rel="stylesheet" href="/assets/css/base.css"><link rel="stylesheet" href="/assets/css/relatorio.css"></head><body><div class="app-shell"><?php renderTopbar('suporte','relatorio');?><main class="app-main"><div class="form-wrap"><a href="/suporte/laboratorio.php?lab=<?=$labAtual?>" class="back-link">← Voltar</a><h1>Novo relatório de ocorrência</h1><?php if($erro):?><p class="empty-state"><?=htmlspecialchars($erro)?></p><?php endif;?><div class="report-card"><form method="post"><div class="field"><label>Laboratório</label><select name="id_lab" onchange="location.href='?lab='+this.value"><?php for($i=1;$i<=4;$i++):?><option value="<?=$i?>" <?=$labAtual===$i?'selected':''?>>Laboratório <?=$i?></option><?php endfor;?></select></div><div class="field"><label for="id_maq">Máquina <span class="required-mark">obrigatória</span></label><select name="id_maq" id="id_maq" required><option value="">Selecione a máquina</option><?php foreach($maquinas as $m):?><option value="<?=$m['ID_MAQ']?>">#<?=$m['ID_MAQ']?><?= $m['apelido']?' — '.htmlspecialchars($m['apelido']):''?><?= $m['numero']!==null?' (baia '.$m['numero'].')':''?></option><?php endforeach;?></select></div><div class="field"><label>Tipo do problema</label><select name="tipo_problema"><?php foreach(tiposProblema() as $t):?><option><?=htmlspecialchars($t)?></option><?php endforeach;?></select></div><div class="field"><label for="titulo">Título</label><input id="titulo" name="titulo" required></div><div class="field"><label>Status</label><div class="status-choice"><input id="defeito" type="radio" name="status" value="1" checked><label for="defeito"><span class="status-dot is-error"></span>Com defeito</label><input id="manutencao" type="radio" name="status" value="2"><label for="manutencao"><span class="status-dot is-warn"></span>Manutenção</label></div></div><div class="field"><label>Data</label><input type="date" name="data" value="<?=date('Y-m-d')?>" required></div><div class="field"><label>Descrição</label><textarea name="descricao" rows="4"></textarea></div><div class="form-actions"><button class="btn btn-accent btn-block" name="sub">Registrar</button></div></form></div></div></main></div></body></html>
